def get_rotational_symmetry(grid, color):
    """Check if shape is rotationally symmetric around its center"""
    pos = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
    if not pos:
        return None

    avg_r = sum(p[0] for p in pos) / len(pos)
    avg_c = sum(p[1] for p in pos) / len(pos)

    for r, c in pos:
        dr, dc = r - avg_r, c - avg_c
        rotated_r = avg_r - dr
        rotated_c = avg_c - dc
        if (rotated_r, rotated_c) not in pos:
            return False
    return True

def get_vertical_symmetry(grid, color):
    """Check if shape has vertical symmetry axis"""
    pos = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
    if not pos:
        return None

    avg_r = sum(p[0] for p in pos) / len(pos)
    avg_c = sum(p[1] for p in pos) / len(pos)

    center_col = int(round(avg_c))
    center_row = int(round(avg_r))

    for r, c in pos:
        mirror_c = 2 * center_col - c
        if (r, mirror_c) not in pos:
