    return True

def analyze_all_colors(grid):
    colors = sorted(set(c for row in grid for c in row if c != 0))
    result = {}
    for color in colors:
        pos = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
